@public create table MyApproxFT(wordapprox countMinSketch({topk:3}));
into table MyApproxFT select countMinSketchAdd(theString) as wordapprox from SupportBean;
@name('frequency') select MyApproxFT.wordapprox.countMinSketchFrequency(p00) as freq from SupportBean_S0;
@name('topk') select MyApproxFT.wordapprox.countMinSketchTopk() as topk from SupportBean_S1;

